export const iconNames = Object.freeze(Object.keys(icons));
export function icon(name, cls='') {
  const item=icons[name]||icons.info;
  const safeClass=String(cls).replace(/[^a-zA-Z0-9_ -]/g,'');
  return `<svg class="icon ${safeClass}" data-icon="${item.set}:${item.name}" viewBox="0 0 ${item.width} ${item.height}" fill="currentColor" stroke="none" aria-hidden="true" focusable="false">${item.body}</svg>`;
}
